/**
 * The bundled signature subset (EXP-S3): selector -> function, topic0 -> event,
 * selector -> error, for contracts with no verified ABI.
 *
 * Data source (Rule 7): src/generated/signatures.json, generated by
 * `pnpm contract:signatures` from the explorer's known ABIs plus the curated
 * standard set (signatureSources.ts). There is no runtime 4byte fetch: an unknown
 * selector stays unknown. A test keeps the committed file in sync.
 */
import {
  type Abi,
  parseAbiItem,
  toEventSelector,
  toFunctionSelector,
  type AbiEvent,
  type AbiFunction,
  type AbiItem,
} from "viem";

type AbiError = Extract<Abi[number], { type: "error" }>;
import bundled from "@/generated/signatures.json";
import { typeLabel } from "./abiForm";

export interface SignatureDb {
  functions: Record<string, string[]>;
  events: Record<string, string[]>;
  errors: Record<string, string[]>;
}

export { knownAbiItems } from "./signatureSources";

function human(item: AbiFunction | AbiEvent | AbiError): string {
  // formatAbiItem drops "function"/"event"/"error" keywords and output names; keep both.
  const outputs = item.type === "function" && item.outputs.length
    ? ` returns (${item.outputs.map((o) => formatParam(o)).join(", ")})`
    : "";
  const mut = item.type === "function" && item.stateMutability !== "nonpayable" ? ` ${item.stateMutability}` : "";
  const inputs = item.inputs.map((p) => formatParam(p, item.type === "event")).join(", ");
  return `${item.type} ${item.name}(${inputs})${mut}${outputs}`;
}

type Param = AbiFunction["inputs"][number] & { indexed?: boolean };

function formatParam(p: Param, withIndexed = false): string {
  const type = p.type.startsWith("tuple")
    ? `(${((p as { components?: Param[] }).components ?? []).map((c) => formatParam(c)).join(", ")})${p.type.slice(5)}`
    : p.type;
  return [type, withIndexed && p.indexed ? "indexed" : "", p.name ?? ""].filter(Boolean).join(" ");
}

/** `name(type,type)` with tuples expanded: what the selector / topic0 hashes. */
export function canonicalSignature(item: AbiFunction | AbiEvent | AbiError): string {
  return `${item.name}(${item.inputs.map((p) => typeLabel(p)).join(",")})`;
}

function add(map: Record<string, string[]>, key: string, value: string) {
  const list = (map[key] ??= []);
  if (!list.includes(value)) list.push(value);
}

/** Build the subset from ABI items. Colliding signatures are kept side by side. */
export function buildSignatureDb(items: readonly AbiItem[]): SignatureDb {
  const db: SignatureDb = { functions: {}, events: {}, errors: {} };
  for (const item of items) {
    if (item.type !== "function" && item.type !== "event" && item.type !== "error") continue;
    const sig = canonicalSignature(item);
    if (item.type === "function") add(db.functions, toFunctionSelector(sig), human(item));
    else if (item.type === "event") add(db.events, toEventSelector(sig), human(item));
    else add(db.errors, toFunctionSelector(sig), human(item));
  }
  const sorted = (m: Record<string, string[]>) =>
    Object.fromEntries(Object.keys(m).sort().map((k) => [k, [...m[k]].sort()]));
  return { functions: sorted(db.functions), events: sorted(db.events), errors: sorted(db.errors) };
}

/** Stable text for the committed file. */
export function serializeSignatureDb(db: SignatureDb): string {
  return JSON.stringify(db, null, 1) + "\n";
}

const DB = bundled as SignatureDb;
const cache = new Map<string, AbiItem>();

function parsed<T extends AbiItem>(text: string): T {
  let v = cache.get(text);
  if (!v) {
    v = parseAbiItem(text) as AbiItem;
    cache.set(text, v);
  }
  return v as T;
}

/** Functions in the subset with this 4-byte selector (several when signatures collide). */
export function lookupFunction(selector: string, db: SignatureDb = DB): AbiFunction[] {
  return (db.functions[selector.toLowerCase()] ?? []).map((t) => parsed<AbiFunction>(t));
}

/** Events in the subset with this topic0. */
export function lookupEvent(topic0: string, db: SignatureDb = DB): AbiEvent[] {
  return (db.events[topic0.toLowerCase()] ?? []).map((t) => parsed<AbiEvent>(t));
}

/** Errors in the subset with this 4-byte selector. */
export function lookupError(selector: string, db: SignatureDb = DB): AbiError[] {
  return (db.errors[selector.toLowerCase()] ?? []).map((t) => parsed<AbiError>(t));
}
